package code;

import java.util.*;

class EnergyMonitor {
    private double maxAllowedUsage;
    private List<String> energyLog;

    public EnergyMonitor(double maxAllowedUsage) {
        this.maxAllowedUsage = maxAllowedUsage;
        this.energyLog = new ArrayList<>();
    }

    public void recordUsage(double energyUsed, double productionOutput) {
        if (energyUsed <= 0 || productionOutput <= 0) {
            System.out.println("Invalid input: Energy usage and production output must be greater than zero.");
            return;
        }

        double efficiency = productionOutput / energyUsed; 
        String message = String.format("Energy Used: %.1f kWh | Production Output: %.1f units | Efficiency: %.2f units/kWh", 
                                       energyUsed, productionOutput, efficiency);

        if (energyUsed > maxAllowedUsage) {
            message += " | WARNING: Energy Overuse Detected! Consider efficiency improvements.";
        }

        System.out.println(message);
        energyLog.add(message);
    }

    public void printEnergyLog() {
        System.out.println("\nEnergy Consumption Log:");
        for (String log : energyLog) {
            System.out.println(log);
        }
    }
}

